	if not Ability1 then
		return
	end

	local CurrentCooldown = Ability1:WaitForChild("CurrentCooldown")
	local Cooldown = Ability1:WaitForChild("Cooldown")

	if p1:GetAttribute("HasToggleAbility") then
		return
	end

	local v1 = CurrentCooldown.Value

	CurrentCooldown.Changed:Connect(function() --[[ Line: 28 | Upvalues: CurrentCooldown (copy), v1 (ref), Cooldown (copy), CurrentStamina (copy), Stamina (copy) ]]
		if v1 < CurrentCooldown.Value and CurrentCooldown.Value >= Cooldown.Value * 0.95 then
			if CurrentStamina.Value < Stamina.Value then
				local v12 = CurrentStamina

				v12.Value = v12.Value + 30
			end

			if CurrentStamina.Value >= Stamina.Value then
				CurrentStamina.Value = Stamina.Value
			end
		end

		v1 = CurrentCooldown.Value
	end)
end
function t.RemoveTrinket(p1) --[[ RemoveTrinket | Line: 44 ]]
